package com.hiresense.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.stereotype.Component; import java.io.IOException;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final AppUserDetailsService users; public JwtAuthenticationFilter(JwtService j,AppUserDetailsService u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7);if(jwt.valid(t)){try{UserDetails u=users.loadUserByUsername(jwt.subject(t));var a=new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities());a.setDetails(new WebAuthenticationDetailsSource().buildDetails(r));SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}}}c.doFilter(r,s);} }
